import { createBrowserClient } from '@supabase/ssr'

// Browser client: publishable key only (R41). NEXT_PUBLIC_* must be referenced literally to be inlined.
export function createClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL
  const key = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY
  if (!url || !key) throw new Error('Supabase URL or publishable key is not set')
  return createBrowserClient(url, key)
}
import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'

// Cookie-bound client for server components and route handlers (publishable key only; R41).
export async function createClient() {
  const cookieStore = await cookies()
  return createServerClient(supabaseUrl(), publishableKey(), {
    cookies: {
      getAll() {
        return cookieStore.getAll()
      },
      setAll(cookiesToSet) {
        try {
          cookiesToSet.forEach(({ name, value, options }) => cookieStore.set(name, value, options))
        } catch {
          // Called from a Server Component, where cookies are read-only: proxy.ts refreshes the session.
        }
      },
    },
  })
}

export function supabaseUrl(): string {
